pc9[image]="kathara/bind"
--- DNS files ---
### pc1/etc/bind/db.root
$TTL 3600
@ IN SOA a.root. hostmaster.root. (
  1 3600 900 604800 300 )
@ IN NS a.root.
a.root. IN A 10.33.0.10

test. IN NS ns1.test.
test. IN NS ns2.test.
ns1.test. IN A 10.33.0.74
ns2.test. IN A 10.33.0.138
### pc1/etc/bind/named.conf
options {
  directory "/var/cache/bind";
  recursion no;
  allow-query { any; };
  dnssec-validation no;
  listen-on { any; };
  listen-on-v6 { any; };
};

zone "." {
  type master;
  file "/etc/bind/db.root";
};
### pc3/etc/bind/db.test
$TTL 3600
@ IN SOA ns1.test. hostmaster.test. (
  1 3600 900 604800 300 )
@ IN NS ns1.test.
@ IN NS ns2.test.
ns1 IN A 10.33.0.74
ns2 IN A 10.33.0.138

www IN A 10.33.1.138
www IN AAAA 2001:db8:1300:7::10
portal IN CNAME www.test.
@ IN MX 10 mail.services.test.

services IN NS ns.services.test.
ns.services IN A 10.33.0.202
### pc3/etc/bind/named.conf
options {
  directory "/var/cache/bind";
  recursion no;
  allow-query { any; };
  dnssec-validation no;
  listen-on { any; };
  listen-on-v6 { any; };
};

zone "test" {
  type master;
  file "/etc/bind/db.test";
  allow-transfer { 10.33.0.138; };
};
### pc5/etc/bind/named.conf
options {
  directory "/var/cache/bind";
  recursion no;
  allow-query { any; };
  dnssec-validation no;
  listen-on { any; };
  listen-on-v6 { any; };
};

zone "test" {
  type slave;
  masters { 10.33.0.74; };
  file "/var/cache/bind/db.test";
};
### pc7/etc/bind/db.services.test
$TTL 3600
@ IN SOA ns.services.test. hostmaster.services.test. (
  1 3600 900 604800 300 )
@ IN NS ns.services.test.
ns IN A 10.33.0.202
mail IN A 10.33.0.202
status IN A 10.33.1.202
@ IN TXT "benchmark=dns-advanced"
### pc7/etc/bind/named.conf
options {
  directory "/var/cache/bind";
  recursion no;
  allow-query { any; };
  dnssec-validation no;
  listen-on { any; };
  listen-on-v6 { any; };
};

zone "services.test" {
  type master;
  file "/etc/bind/db.services.test";
};
### pc9/etc/bind/db.hints
. 3600000 IN NS a.root.
a.root. 3600000 IN A 10.33.0.10
### pc9/etc/bind/named.conf
options {
  directory "/var/cache/bind";
  recursion yes;
  allow-recursion { any; };
  allow-query { any; };
  dnssec-validation no;
  listen-on { any; };
  listen-on-v6 { any; };
};

zone "." {
  type hint;
  file "/etc/bind/db.hints";
};
